def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of xs, averaging the two middle values when even."""
    ordered = sorted(xs)
    if not ordered:
        raise ValueError("median() arg is an empty sequence")
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

